using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;

public class FinanceService(AppDb db,Access access,CommunityService community) {
 public static readonly string[] Permissions=["finance.read","finance.configure","finance.dues","finance.invoice","finance.collect","finance.approve","finance.post","finance.periods","finance.bank","finance.reconcile","finance.refund","finance.budget","finance.expense","finance.export","finance.highvalue","finance.providers","finance.interentity"];
 public static readonly Dictionary<string,int> Currencies=new(){["INR"]=2,["USD"]=2,["EUR"]=2,["GBP"]=2,["AED"]=2,["SAR"]=2,["AUD"]=2,["CAD"]=2,["SGD"]=2,["JPY"]=0,["KWD"]=3,["BHD"]=3,["OMR"]=3};
 public static string[] TemplatePermissions(string name)=>name.Contains("Treasurer")?Permissions.Where(p=>p is not("finance.configure" or "finance.providers" or "finance.periods" or "finance.highvalue")).Concat(new[]{"communications.send","communications.templates"}).ToArray():name.Contains("President")||name.Contains("Governor")||name.Contains("Secretary")||name.Contains("Manager")?["finance.read"]:[];
 public static decimal MinorFactor(string currency)=>Currencies.TryGetValue(currency,out var digits)?digits switch{0=>1m,2=>100m,3=>1000m,_=>throw new DomainException("Unsupported currency precision")}:throw new DomainException("Unsupported currency");
 public static decimal Round(decimal value,string currency){if(!Currencies.TryGetValue(currency,out var digits))throw new DomainException("Choose a supported currency");return Math.Round(value,digits,MidpointRounding.AwayFromZero);}
 public static void Money(decimal value,string currency,bool positive=true){if((positive?value<=0:value<0)||value>1000000000000m||Round(value,currency)!=value)throw new DomainException("Amount must be within the currency's minor-unit precision and permitted range");}
 void Audit(Guid tenant,Guid actor,string action,Guid resource,object? details=null)=>db.Add(new Audit{TenantId=tenant,ActorId=actor,Action=action,ResourceId=resource,Details=JsonSerializer.Serialize(details??new{})});
 public static DateOnly Today=>DateOnly.FromDateTime(DateTime.UtcNow);
 public static Task Lock(AppDb db,Guid tenant)=>MembershipService.Lock(db,tenant);
 public IQueryable<T> Scoped<T>(Guid tenant,string permission="finance.read",Guid? entity=null,Guid? workspace=null)where T:FinanceRecord{var units=access.InWorkspace(access.Visible(tenant,permission),tenant,workspace).Select(u=>u.Id);return db.Set<T>().AsNoTracking().Where(x=>x.TenantId==tenant&&(entity==null||x.EntityId==entity)&&x.UnitId!=null&&units.Contains(x.UnitId.Value));}
 public async Task<FinancialEntity> Require(Guid tenant,Guid entity,Guid? unit,string permission="finance.read"){
  await access.Member(tenant);var e=await db.Set<FinancialEntity>().SingleOrDefaultAsync(e=>e.TenantId==tenant&&e.Id==entity&&(e.Active||permission=="finance.read"||permission=="finance.export"))??throw new AccessDeniedException();
  if(permission is "finance.configure" or "finance.providers" or "finance.periods")await access.Require(tenant,permission,e.UnitId);if(unit==null){if(!await access.Can(tenant,permission)&&!await db.Set<FinancialUnit>().AnyAsync(u=>u.TenantId==tenant&&u.EntityId==entity&&u.UnitId!=null&&access.Visible(tenant,permission).Select(x=>x.Id).Contains(u.UnitId.Value)))throw new AccessDeniedException();}
  else{await access.Require(tenant,permission,unit);if(!await db.Set<FinancialUnit>().AnyAsync(u=>u.TenantId==tenant&&u.EntityId==entity&&u.UnitId==unit))throw new DomainException("Organization is not assigned to this legal/accounting entity");}return e;
 }
 public async Task<bool> Own(FinanceInvoice i){var now=DateTimeOffset.UtcNow;return i.MembershipId!=null&&await db.Memberships.AnyAsync(m=>m.TenantId==i.TenantId&&m.Id==i.MembershipId&&MembershipExperience.Owned(db,access.UserId,true).Select(own=>own.Id).Contains(m.Id))||i.RegistrationId!=null&&await db.Set<EventRegistration>().AnyAsync(r=>r.TenantId==i.TenantId&&r.Id==i.RegistrationId&&r.UserId==access.UserId);}
 public async Task<FinanceInvoice> Invoice(Guid tenant,Guid id,bool self=true){await access.Member(tenant);var i=await db.Set<FinanceInvoice>().SingleOrDefaultAsync(i=>i.TenantId==tenant&&i.Id==id)??throw new AccessDeniedException();if(!(self&&i.Status=="Issued"&&await Own(i)))await Require(tenant,i.EntityId,i.UnitId);return i;}
 public static string PaymentStatus(FinanceInvoice i)=>i.Kind=="Credit"&&i.Status=="Issued"?"Applied":i.Status!="Issued"?i.Status:i.Total-i.Paid-i.Credited<=0?"Paid":i.Paid>0?"Partially Paid":i.DueOn<Today?"Overdue":"Unpaid";
 public async Task<FinancialEntity> CreateEntity(Guid tenant,FinanceEntityWrite r){await access.Require(tenant,"finance.configure",r.UnitId);if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.LegalName)||r.Name.Length>160||r.LegalName.Length>200||r.Address.Length>2000||r.TaxRegistration.Length>200||r.FiscalMonth is <1 or >12||!Currencies.ContainsKey(r.Currency)||!System.Text.RegularExpressions.Regex.IsMatch(r.InvoicePrefix,@"^[A-Z0-9-]{1,12}$")||!System.Text.RegularExpressions.Regex.IsMatch(r.ReceiptPrefix,@"^[A-Z0-9-]{1,12}$"))throw new DomainException("Check legal entity details, fiscal month, currency and numbering prefixes");Money(r.ApprovalLimit,r.Currency,false);var units=(r.Units??(r.UnitId==null?[]:[r.UnitId.Value])).Distinct().ToArray();if(units.Length is <1 or >100000)throw new DomainException("Assign at least one organization to the financial entity");if(!await access.Can(tenant,"finance.configure")){var permitted=await access.Visible(tenant,"finance.configure").Where(u=>units.Contains(u.Id)).Select(u=>u.Id).ToArrayAsync();if(permitted.Length!=units.Length)throw new AccessDeniedException();}if(await db.Units.CountAsync(u=>u.TenantId==tenant&&units.Contains(u.Id))!=units.Length)throw new AccessDeniedException();var entity=new FinancialEntity{TenantId=tenant,UnitId=r.UnitId,Name=r.Name.Trim(),LegalName=r.LegalName.Trim(),Active=r.Active,Currency=r.Currency,Country=r.Country,Address=r.Address,TaxRegistration=r.TaxRegistration,FiscalMonth=r.FiscalMonth,RequireInvoiceApproval=r.RequireInvoiceApproval,ApprovalLimit=r.ApprovalLimit,InvoicePrefix=r.InvoicePrefix,ReceiptPrefix=r.ReceiptPrefix};db.Add(entity);foreach(var unit in units)db.Add(new FinancialUnit{TenantId=tenant,EntityId=entity.Id,UnitId=unit});
  foreach(var (code,name,type) in new(string,string,string)[]{("1000","Cash","Asset"),("1010","Bank","Asset"),("1020","Gateway clearing","Asset"),("1100","Accounts receivable","Asset"),("1200","Inter-entity receivable","Asset"),("2000","Accounts payable","Liability"),("2100","Tax payable","Liability"),("2200","Unapplied member advances","Liability"),("2300","Deferred income","Liability"),("2400","Inter-entity payable","Liability"),("3000","General fund","Equity"),("3100","Restricted fund","Equity"),("3200","Accumulated surplus","Equity"),("4000","Membership dues","Income"),("4100","Chapter affiliation fees","Income"),("4200","Event revenue","Income"),("4300","Donations","Income"),("4400","Sponsorships","Income"),("4500","Other income","Income"),("5000","Chapter operations","Expense"),("5100","Meetings and events","Expense"),("5200","Service activities","Expense"),("5300","Communication","Expense"),("5400","Training","Expense"),("5500","Administration","Expense")})db.Add(new LedgerAccount{TenantId=tenant,EntityId=entity.Id,UnitId=entity.UnitId??units[0],Code=code,Name=name,Type=type,Control=new[]{"1100","1200","2000","2100","2200","2400"}.Contains(code)});
  var fiscalStart=new DateOnly(Today.Month>=r.FiscalMonth?Today.Year:Today.Year-1,r.FiscalMonth,1);for(var n=0;n<12;n++)db.Add(new AccountingPeriod{TenantId=tenant,EntityId=entity.Id,UnitId=entity.UnitId??units[0],Name=fiscalStart.AddMonths(n).ToString("yyyy MMM"),StartsOn=fiscalStart.AddMonths(n),EndsOn=fiscalStart.AddMonths(n+1).AddDays(-1)});access.Audit(tenant,"finance.entity.created",entity.Id,new{entity.Currency,units});return entity;
 }
 public async Task<JournalEntry> Post(FinancialEntity entity,Guid unit,DateOnly date,string purpose,string source,Guid sourceId,string key,IEnumerable<JournalInput> input,Guid author,Guid? reviewer=null,Guid? member=null,Guid? counterpartyUnit=null,Guid? reverse=null,Guid? invoice=null){var old=await db.Set<JournalEntry>().SingleOrDefaultAsync(j=>j.TenantId==entity.TenantId&&j.EntityId==entity.Id&&j.SourceKey==key);if(old!=null)return old;var rows=input.ToArray();if(rows.Length is <2 or >100||rows.Any(l=>l.Debit<0||l.Credit<0||l.Debit>0&&l.Credit>0||l.Debit==0&&l.Credit==0)||rows.Sum(l=>l.Debit)!=rows.Sum(l=>l.Credit)||rows.Sum(l=>l.Debit)<=0)throw new DomainException("Journal needs balanced positive debit/credit lines");foreach(var row in rows){Money(row.Debit,entity.Currency,false);Money(row.Credit,entity.Currency,false);}var period=await db.Set<AccountingPeriod>().SingleOrDefaultAsync(p=>p.TenantId==entity.TenantId&&p.EntityId==entity.Id&&p.StartsOn<=date&&p.EndsOn>=date&&!p.Closed)??throw new DomainException("Posting date is outside an open accounting period");var codes=rows.Select(l=>l.AccountCode).Distinct().ToArray();var accounts=await db.Set<LedgerAccount>().Where(a=>a.TenantId==entity.TenantId&&a.EntityId==entity.Id&&a.Active&&codes.Contains(a.Code)).ToDictionaryAsync(a=>a.Code);if(accounts.Count!=codes.Length)throw new DomainException("Use active accounts from the posting entity's chart");var journal=new JournalEntry{TenantId=entity.TenantId,EntityId=entity.Id,UnitId=unit,PeriodId=period.Id,Number="JRN-"+(entity.NextJournal++).ToString("D7"),Date=date,Currency=entity.Currency,Purpose=purpose,SourceKind=source,SourceId=sourceId,SourceKey=key,AuthorId=author,ApprovedBy=reviewer,ReversesId=reverse};db.Add(journal);foreach(var line in rows)db.Add(new JournalLine{TenantId=entity.TenantId,EntityId=entity.Id,UnitId=unit,JournalId=journal.Id,AccountId=accounts[line.AccountCode].Id,Debit=line.Debit,Credit=line.Credit,Memo=line.Memo,MembershipId=member,CounterpartyUnitId=counterpartyUnit,InvoiceId=invoice});await db.SaveChangesAsync();journal.Posted=true;journal.PostedAt=DateTimeOffset.UtcNow;Audit(entity.TenantId,author,"finance.journal.posted",journal.Id,new{journal.SourceKind,journal.SourceId});await db.SaveChangesAsync();return journal;}
 public async Task<FinanceInvoice> CreateInvoice(Guid tenant,InvoiceWrite r,bool policyAuthorized=false){var entity=policyAuthorized?await db.Set<FinancialEntity>().SingleAsync(e=>e.TenantId==tenant&&e.Id==r.EntityId&&e.Active):await Require(tenant,r.EntityId,r.UnitId,"finance.invoice");if(r.Lines.Length is <1 or >60||r.DueOn<r.Date||r.Notes.Length>4000||r.CounterpartyName.Length>200||r.Purpose.Length>160)throw new DomainException("Check invoice lines, dates and notes");if(new object?[]{r.MembershipId,r.BilledUnitId,r.DonorId}.Count(x=>x!=null)>1)throw new DomainException("Choose one canonical invoice counterparty");var name=r.CounterpartyName;var address="";if(r.MembershipId!=null){var m=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==r.MembershipId)??throw new AccessDeniedException();if(m.ChapterId!=r.UnitId)throw new DomainException("Member invoice owner must be its authorized chapter");name=await db.Persons.Where(p=>p.Id==m.PersonId).Select(p=>p.FullName).SingleAsync();}if(r.BilledUnitId!=null){var u=await db.Units.SingleOrDefaultAsync(u=>u.TenantId==tenant&&u.Id==r.BilledUnitId)??throw new AccessDeniedException();await access.Require(tenant,"finance.invoice",u.Id);name=u.Name;}if(r.DonorId!=null){var donor=await db.Set<FinanceDonor>().SingleOrDefaultAsync(d=>d.TenantId==tenant&&d.EntityId==entity.Id&&d.Id==r.DonorId)??throw new AccessDeniedException();name=donor.Name;}if(string.IsNullOrWhiteSpace(name))throw new DomainException("Choose a billed party");if(r.EventId!=null){var e=await db.Set<CommunityEvent>().SingleOrDefaultAsync(e=>e.TenantId==tenant&&e.Id==r.EventId)??throw new AccessDeniedException();if(e.UnitId!=r.UnitId)throw new AccessDeniedException();}
 var lines=new List<object>();decimal subtotal=0,discount=0,tax=0;foreach(var line in r.Lines){if(string.IsNullOrWhiteSpace(line.Description)||line.Description.Length>500||line.Quantity<=0||line.Quantity>1000000||line.DiscountPercent is <0 or >100||line.TaxPercent is <0 or >100)throw new DomainException("Check line quantity, description and percentages");Money(line.UnitPrice,entity.Currency,false);var account=await db.Set<LedgerAccount>().SingleOrDefaultAsync(a=>a.TenantId==tenant&&a.EntityId==entity.Id&&a.Code==line.AccountCode&&a.Active&&a.Type=="Income")??throw new DomainException("Invoice lines require an active income account");var gross=Round(line.Quantity*line.UnitPrice,entity.Currency);var less=Round(gross*line.DiscountPercent/100,entity.Currency);var lineTax=Round((gross-less)*line.TaxPercent/100,entity.Currency);subtotal+=gross;discount+=less;tax+=lineTax;lines.Add(new{line.Description,line.Quantity,line.UnitPrice,line.DiscountPercent,line.TaxPercent,line.AccountCode,gross,discount=less,tax=lineTax,total=gross-less+lineTax});}var total=subtotal-discount+tax;Money(total,entity.Currency,false);var invoice=new FinanceInvoice{TenantId=tenant,EntityId=entity.Id,UnitId=r.UnitId,AuthorId=access.UserId,MembershipId=r.MembershipId,BilledUnitId=r.BilledUnitId,DonorId=r.DonorId,EventId=r.EventId,CounterpartyName=name,CounterpartyAddress=address,Date=r.Date,DueOn=r.DueOn,Currency=entity.Currency,Lines=JsonSerializer.Serialize(lines),Subtotal=subtotal,Discount=discount,Tax=tax,Total=total,Notes=r.Notes,Purpose=r.Purpose,Status=r.Submit?"Pending Approval":"Draft"};db.Add(invoice);access.Audit(tenant,"finance.invoice.created",invoice.Id);return invoice;
 }
 public async Task Issue(FinanceInvoice i,FinancialEntity e,Guid? reviewer=null){if(i.Status=="Issued")return;if(i.Status is not("Draft" or "Pending Approval"))throw new DomainException("Invoice cannot be issued in its current state");if(e.RequireInvoiceApproval&&reviewer==null)throw new DomainException("Independent invoice approval is required");if(i.Total>e.ApprovalLimit)await access.Require(i.TenantId,"finance.highvalue",i.UnitId);if(i.Total==0){i.Number=e.InvoicePrefix+"-"+i.Date.Year+"-"+(e.NextInvoice++).ToString("D7");i.Status="Issued";i.ApprovedBy=reviewer;i.IssuerSnapshot=JsonSerializer.Serialize(new{e.LegalName,e.Address,e.TaxRegistration,e.Currency,e.Country});i.Revision++;await db.SaveChangesAsync();return;}if(i.Kind=="Credit"){var original=await db.Set<FinanceInvoice>().SingleAsync(o=>o.TenantId==i.TenantId&&o.EntityId==i.EntityId&&o.Id==i.OriginalId&&o.Kind=="Invoice"&&o.Status=="Issued");if(i.Total>original.Total-original.Paid-original.Credited)throw new DomainException("Credit exceeds current uncollected outstanding");i.Tax=Round(i.Total*original.Tax/original.Total,i.Currency);i.Subtotal=i.Total-i.Tax;var originalLines=JsonSerializer.Deserialize<JsonElement[]>(original.Lines)!;var groups=originalLines.GroupBy(l=>l.GetProperty("AccountCode").GetString()!).ToArray();var correction=new List<JournalInput>{new("1100",0,i.Total)};decimal remaining=i.Subtotal;for(var n=0;n<groups.Length;n++){var net=groups[n].Sum(l=>l.GetProperty("gross").GetDecimal()-l.GetProperty("discount").GetDecimal());var part=n==groups.Length-1?remaining:Round(i.Subtotal*net/(original.Subtotal-original.Discount),i.Currency);remaining-=part;if(part>0)correction.Add(new(groups[n].Key,part,0));}if(i.Tax>0)correction.Add(new("2100",i.Tax,0));var journal=await Post(e,i.UnitId!.Value,i.Date,i.Notes,"Credit",i.Id,"credit:"+i.Id,correction,i.AuthorId,reviewer,i.MembershipId,i.BilledUnitId,invoice:original.Id);original.Credited+=i.Total;original.Revision++;i.JournalId=journal.Id;i.Number="CN-"+i.Date.Year+"-"+(e.NextInvoice++).ToString("D7");i.Status="Issued";i.ApprovedBy=reviewer;i.IssuerSnapshot=original.IssuerSnapshot;i.Revision++;await db.SaveChangesAsync();return;}var lines=JsonSerializer.Deserialize<JsonElement[]>(i.Lines)!;var journalLines=new List<JournalInput>{new("1100",i.Total,0,i.CounterpartyName)};foreach(var group in lines.GroupBy(l=>l.GetProperty("AccountCode").GetString()!)){var amount=group.Sum(l=>l.GetProperty("gross").GetDecimal()-l.GetProperty("discount").GetDecimal());if(amount>0)journalLines.Add(new(group.Key,0,amount));}if(i.Tax>0)journalLines.Add(new("2100",0,i.Tax));var j=await Post(e,i.UnitId!.Value,i.Date,i.Purpose,"Invoice",i.Id,"invoice:"+i.Id,journalLines,i.AuthorId,reviewer,i.MembershipId,i.BilledUnitId,invoice:i.Id);i.Number=e.InvoicePrefix+"-"+i.Date.Year+"-"+(e.NextInvoice++).ToString("D7");i.Status="Issued";i.ApprovedBy=reviewer;i.JournalId=j.Id;i.IssuerSnapshot=JsonSerializer.Serialize(new{e.LegalName,e.Address,e.TaxRegistration,e.Currency,e.Country});i.Revision++;access.Audit(i.TenantId,"finance.invoice.issued",i.Id);await FinanceCommunication.NotifyChapter(i,db);await FinanceCommunication.NotifyMember(i,i.MembershipId,"Invoice "+i.Number+" issued",i.Currency+" "+i.Total+" due "+i.DueOn,"finance-issued:"+i.Id,db);await db.SaveChangesAsync();}
 public async Task Review(Guid tenant,Guid id,Guid author,Guid unit,string kind,FinanceDecision r,decimal amount,FinancialEntity entity){await Require(tenant,entity.Id,unit,"finance.approve");if(amount>entity.ApprovalLimit)await access.Require(tenant,"finance.highvalue",unit);await community.Decision(tenant,id,author,unit,kind,"[\"finance.approve\"]",0,new(r.Decision,r.Note,r.Revision));}
 public async Task<FinancePayment> Record(Guid tenant,PaymentWrite r){var e=await Require(tenant,r.EntityId,r.UnitId,"finance.collect");Money(r.Amount,e.Currency);if(!new[]{"Cash","Bank transfer","Cheque","UPI","Card","Net banking","Manual"}.Contains(r.Method)||r.Reference.Length is <3 or >160||r.Payer.Length is <1 or >200||r.Notes.Length>2000)throw new DomainException("Check payment method, payer and unique reference");if(new object?[]{r.MembershipId,r.PayerUnitId,r.DonorId}.Count(x=>x!=null)>1)throw new DomainException("Choose one payment counterparty");if(r.MembershipId!=null&&!await db.Memberships.AnyAsync(m=>m.TenantId==tenant&&m.Id==r.MembershipId&&m.ChapterId==r.UnitId))throw new AccessDeniedException();if(r.PayerUnitId!=null)await access.Require(tenant,"finance.collect",r.PayerUnitId);if(r.DonorId!=null&&!await db.Set<FinanceDonor>().AnyAsync(d=>d.TenantId==tenant&&d.EntityId==e.Id&&d.Id==r.DonorId))throw new AccessDeniedException();if(r.BankId!=null){var bank=await db.Set<FinanceBank>().SingleOrDefaultAsync(b=>b.TenantId==tenant&&b.EntityId==e.Id&&b.Id==r.BankId&&b.Active)??throw new AccessDeniedException();await Require(tenant,e.Id,bank.UnitId,"finance.bank");}var payment=new FinancePayment{TenantId=tenant,EntityId=e.Id,UnitId=r.UnitId,AuthorId=access.UserId,Amount=r.Amount,Reference=r.Reference.Trim(),Date=r.Date,Payer=r.Payer,Method=r.Method,MembershipId=r.MembershipId,PayerUnitId=r.PayerUnitId,DonorId=r.DonorId,Currency=e.Currency,BankId=r.BankId,Notes=r.Notes};db.Add(payment);access.Audit(tenant,"finance.payment.recorded",payment.Id);return payment;}
 public async Task Confirm(FinancePayment p,FinancialEntity e,Guid? reviewer,bool gateway=false){if(p.Status=="Confirmed")return;if(p.Status!="Pending Approval"&&p.Status!="Pending Clearance")throw new DomainException("Payment cannot be confirmed");if(!gateway&&reviewer==p.AuthorId)throw new AccessDeniedException();var debit=p.ProviderId!=null?"1020":p.Method=="Cash"?"1000":p.BankId==null?"1010":await db.Set<FinanceBank>().Where(b=>b.Id==p.BankId&&b.EntityId==e.Id).Select(b=>b.AccountCode).SingleAsync();var journal=await Post(e,p.UnitId!.Value,p.Date,"Payment received: "+p.Reference,"Payment",p.Id,"payment:"+p.Id,[new(debit,p.Amount,0),new("2200",0,p.Amount)],p.AuthorId,reviewer,p.MembershipId,p.PayerUnitId);p.Status="Confirmed";p.ApprovedBy=reviewer;p.JournalId=journal.Id;var receipt=new FinanceReceipt{TenantId=p.TenantId,EntityId=e.Id,UnitId=p.UnitId,PaymentId=p.Id,Amount=p.Amount,Currency=p.Currency,Number=e.ReceiptPrefix+"-"+p.Date.Year+"-"+(e.NextReceipt++).ToString("D7"),Snapshot=JsonSerializer.Serialize(new{e.LegalName,e.Address,e.TaxRegistration,p.Payer,p.Amount,p.Currency,p.Method,p.Reference,p.Date})};db.Add(receipt);Audit(p.TenantId,reviewer??p.AuthorId,"finance.payment.confirmed",p.Id);await FinanceCommunication.NotifyMember(p,p.MembershipId,"Payment received · receipt available",p.Currency+" "+p.Amount+" confirmed. Receipt "+receipt.Number,"finance-payment:"+p.Id,db);await db.SaveChangesAsync();}
 public async Task<PaymentAllocation> Allocate(FinancePayment p,FinanceInvoice i,decimal amount,string key,Guid actor){Money(amount,p.Currency);if(p.Status!="Confirmed"||i.Status!="Issued"||i.Kind!="Invoice"||i.EntityId!=p.EntityId||p.Currency!=i.Currency||p.TenantId!=i.TenantId)throw new DomainException("Allocation needs confirmed funds and an issued invoice in the same entity/currency");if(p.MembershipId!=i.MembershipId||p.PayerUnitId!=i.BilledUnitId||p.DonorId!=i.DonorId)throw new DomainException("Payment and invoice counterparties must match");if(p.UnitId!=i.UnitId)throw new DomainException("Payment and invoice organizational owners must match");var existing=await db.Set<PaymentAllocation>().SingleOrDefaultAsync(a=>a.TenantId==p.TenantId&&a.EntityId==p.EntityId&&a.Key==key);if(existing!=null){if(existing.PaymentId!=p.Id||existing.InvoiceId!=i.Id||existing.Amount!=amount)throw new DomainException("Allocation key was already used with different values");return existing;}if(i.EventId!=null&&p.ProviderId==null&&await db.Set<EventFinancePolicy>().AnyAsync(policy=>policy.TenantId==i.TenantId&&policy.EventId==i.EventId&&!policy.AllowManualSettlement))throw new DomainException("This event requires a verified gateway payment");var used=await db.Set<PaymentAllocation>().Where(a=>a.PaymentId==p.Id).SumAsync(a=>a.Amount);if(amount>p.Amount-p.Refunded-p.ChargedBack-used||amount>i.Total-i.Paid-i.Credited)throw new DomainException("Allocation exceeds available funds or invoice outstanding");var e=await db.Set<FinancialEntity>().SingleAsync(e=>e.Id==p.EntityId&&e.TenantId==p.TenantId);var id=Guid.NewGuid();var j=await Post(e,i.UnitId!.Value,Today,"Invoice allocation "+i.Number,"Allocation",id,"allocation:"+key,[new("2200",amount,0),new("1100",0,amount)],actor,null,i.MembershipId,i.BilledUnitId,invoice:i.Id);var allocation=new PaymentAllocation{Id=id,TenantId=p.TenantId,EntityId=p.EntityId,UnitId=i.UnitId,InvoiceId=i.Id,PaymentId=p.Id,Amount=amount,Key=key,JournalId=j.Id};db.Add(allocation);i.Paid+=amount;i.Revision++;await db.SaveChangesAsync();if(i.RegistrationId!=null&&i.Total-i.Paid-i.Credited<=0)await ConfirmEvent(i);await MembershipExperience.ReconcileInvoice(db,i,actor); Audit(p.TenantId,actor,"finance.payment.allocated",id,new{i.Id,amount});return allocation;}
 public async Task ConfirmEvent(FinanceInvoice i){await EventEndpoints.Lock(db,i.TenantId,i.EventId!.Value);var registration=await db.Set<EventRegistration>().SingleAsync(r=>r.TenantId==i.TenantId&&r.Id==i.RegistrationId);var e=await db.Set<CommunityEvent>().SingleAsync(e=>e.TenantId==i.TenantId&&e.Id==registration.EventId);if(e.Status!="Published"||registration.Status!="Awaiting Payment")return;var occupied=await db.Set<EventRegistration>().Where(r=>r.TenantId==i.TenantId&&r.EventId==e.Id&&r.Status=="Confirmed").SumAsync(r=>r.Companions+1);registration.Status=occupied+registration.Companions+1<=e.Capacity?"Confirmed":"Waitlisted";registration.Revision++;await db.SaveChangesAsync();}
 public async Task CompleteRefund(FinanceRefund refund,FinancePayment p,FinancialEntity e,Guid reviewer,string? providerReference=null){if(refund.Status=="Processed")return;Money(refund.Amount,p.Currency);if(p.Status!="Confirmed"||refund.Amount>p.Amount-p.Refunded-p.ChargedBack)throw new DomainException("Refund exceeds the confirmed refundable amount");var allocations=await db.Set<PaymentAllocation>().Where(a=>a.PaymentId==p.Id&&a.Amount>0).OrderByDescending(a=>a.At).ToListAsync();var used=allocations.Sum(a=>a.Amount);var release=Math.Max(0,refund.Amount-(p.Amount-p.Refunded-p.ChargedBack-used));foreach(var allocation in allocations){if(release<=0)break;var amount=Math.Min(release,allocation.Amount);var invoice=await db.Set<FinanceInvoice>().SingleAsync(i=>i.Id==allocation.InvoiceId&&i.EntityId==p.EntityId);await Post(e,invoice.UnitId!.Value,refund.Date,"Refund allocation reversal "+invoice.Number,"RefundAllocation",refund.Id,"refund-allocation:"+refund.Id+":"+allocation.Id,[new("1100",amount,0),new("2200",0,amount)],refund.AuthorId,reviewer,invoice.MembershipId,invoice.BilledUnitId,invoice:invoice.Id);allocation.Amount-=amount;invoice.Paid-=amount;invoice.Revision++;await MembershipExperience.ReconcileInvoice(db,invoice,reviewer);release-=amount;if(invoice.RegistrationId!=null){await db.Set<EventPass>().Where(pass=>pass.RegistrationId==invoice.RegistrationId&&pass.RevokedAt==null).ExecuteUpdateAsync(x=>x.SetProperty(pass=>pass.RevokedAt,DateTimeOffset.UtcNow));var reg=await db.Set<EventRegistration>().SingleAsync(r=>r.Id==invoice.RegistrationId);reg.Status="Awaiting Payment";reg.Revision++;}}
 var cash=p.ProviderId!=null?"1020":p.Method=="Cash"?"1000":p.BankId==null?"1010":await db.Set<FinanceBank>().Where(b=>b.Id==p.BankId).Select(b=>b.AccountCode).SingleAsync();var j=await Post(e,p.UnitId!.Value,refund.Date,"Refund: "+refund.Reason,refund.Kind=="Chargeback"?"Chargeback":"Refund",refund.Id,"refund:"+refund.Id,[new("2200",refund.Amount,0),new(cash,0,refund.Amount)],refund.AuthorId,reviewer,p.MembershipId,p.PayerUnitId);refund.Status="Processed";refund.ApprovedBy=reviewer;refund.JournalId=j.Id;refund.ProviderReference=providerReference;if(refund.Kind=="Chargeback")p.ChargedBack+=refund.Amount;else p.Refunded+=refund.Amount;Audit(p.TenantId,reviewer,"finance.refund.processed",refund.Id);await FinanceCommunication.NotifyMember(p,p.MembershipId,refund.Kind=="Chargeback"?"Verified chargeback recorded":"Refund processed",refund.Currency+" "+refund.Amount+"; view the statement for updated allocation and balance.","finance-refund:"+refund.Id,db);await db.SaveChangesAsync();}
 public async Task<DuesAssessment> Assess(DuesPlan plan,DateOnly start,DateOnly end,Guid? memberId,Guid? chapterId){var e=await Require(plan.TenantId,plan.EntityId,chapterId??plan.UnitId,"finance.dues");if(!plan.Active||end<start||start<plan.EffectiveFrom||plan.EffectiveTo!=null&&end>plan.EffectiveTo||end.DayNumber-start.DayNumber>366)throw new DomainException("Billing period is outside active plan dates");if(plan.Target=="Member"&&memberId==null||plan.Target=="Chapter"&&chapterId==null)throw new DomainException("Assessment counterparty does not match its rule");var key=memberId?.ToString()??chapterId!.ToString()!;var existing=await db.Set<DuesAssessment>().SingleOrDefaultAsync(d=>d.TenantId==plan.TenantId&&d.EntityId==plan.EntityId&&d.PlanId==plan.Id&&d.CounterpartyKey==key&&d.StartsOn==start);if(existing!=null){if(existing.EndsOn!=end)throw new DomainException("Existing assessment period differs");return existing;}if(await db.Set<DuesAssessment>().AnyAsync(d=>d.TenantId==plan.TenantId&&d.PlanId==plan.Id&&d.CounterpartyKey==key&&d.StartsOn<=end&&d.EndsOn>=start))throw new DomainException("Assessment overlaps an existing billed period");var months=plan.Frequency switch{"Monthly"=>1,"Quarterly"=>3,"Half-yearly"=>6,"Annual"=>12,_=>0};if(months>0&&start.AddMonths(months).AddDays(-1)!=end)throw new DomainException("Billing dates must match the configured frequency");Membership? member=null;if(memberId!=null){member=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==plan.TenantId&&m.Id==memberId&&m.Status=="Active"&&m.EffectiveFrom<DateTime.SpecifyKind(end.ToDateTime(TimeOnly.MaxValue),DateTimeKind.Utc)&&(m.EndsAt==null||m.EndsAt>DateTime.SpecifyKind(start.ToDateTime(TimeOnly.MinValue),DateTimeKind.Utc)))??throw new DomainException("No eligible active membership in the assessment period");if(plan.CategoryId!=null&&member.CategoryId!=plan.CategoryId)throw new DomainException("Membership category does not match the rule");chapterId=member.ChapterId;await Require(plan.TenantId,plan.EntityId,chapterId,"finance.dues");if(plan.Frequency=="Once"&&await db.Set<DuesAssessment>().AnyAsync(d=>d.PlanId==plan.Id&&d.MembershipId==memberId))throw new DomainException("One-time/life dues were already assessed");}
 if(chapterId==null||!await db.Units.AnyAsync(u=>u.TenantId==plan.TenantId&&u.Id==chapterId&&u.Status=="Active"&&db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Chapter")))throw new DomainException("Choose an active chapter");var count=plan.Target=="Chapter"?await db.Memberships.CountAsync(m=>m.TenantId==plan.TenantId&&m.ChapterId==chapterId&&m.Status=="Active"&&m.EffectiveFrom<=DateTime.SpecifyKind(start.ToDateTime(TimeOnly.MinValue),DateTimeKind.Utc)&&(m.EndsAt==null||m.EndsAt>DateTime.SpecifyKind(start.ToDateTime(TimeOnly.MinValue),DateTimeKind.Utc))&&(plan.CategoryId==null||m.CategoryId==plan.CategoryId)):0;var gross=plan.Amount+plan.PerMember*count;decimal fraction=1;if(member!=null&&plan.Proration=="Daily"){var from=DateOnly.FromDateTime(member.EffectiveFrom.UtcDateTime);var to=member.EndsAt==null?end:DateOnly.FromDateTime(member.EndsAt.Value.UtcDateTime).AddDays(-1);fraction=(Math.Min(end.DayNumber,to.DayNumber)-Math.Max(start.DayNumber,from.DayNumber)+1m)/(end.DayNumber-start.DayNumber+1m);fraction=Math.Clamp(fraction,0,1);}var exemption=await db.Set<DuesExemption>().Where(x=>x.TenantId==plan.TenantId&&x.PlanId==plan.Id&&x.ApprovedBy!=null&&x.StartsOn<=start&&x.EndsOn>=end&&(memberId!=null&&x.MembershipId==memberId||memberId==null&&x.ChapterId==chapterId)).Select(x=>(decimal?)x.Percent).MaxAsync()??0;var billed=Round(Round(gross*fraction,e.Currency)*(1-plan.DiscountPercent/100)*(1-exemption/100),e.Currency);var invoice=await CreateInvoice(plan.TenantId,new(plan.EntityId,chapterId.Value,plan.Target+" dues",Today,Today>start.AddDays(plan.GraceDays)?Today.AddDays(plan.GraceDays):start.AddDays(plan.GraceDays),[new(plan.Name+" "+start.ToString("yyyy-MM-dd")+" to "+end.ToString("yyyy-MM-dd"),1,billed,0,0,plan.IncomeCode)],memberId,memberId==null?chapterId:null,Purpose:plan.Kind,Submit:plan.RequiresApproval));var assessment=new DuesAssessment{TenantId=plan.TenantId,EntityId=plan.EntityId,UnitId=chapterId,PlanId=plan.Id,MembershipId=memberId,ChapterId=memberId==null?chapterId:null,CounterpartyKey=key,StartsOn=start,EndsOn=end,DueOn=invoice.DueOn,MemberCount=count,BaseAmount=plan.Amount,PerMemberAmount=plan.PerMember,Discount=gross-billed,Total=billed,Currency=e.Currency,InvoiceId=invoice.Id,Snapshot=JsonSerializer.Serialize(new{plan.Id,plan.Revision,plan.Amount,plan.PerMember,plan.DiscountPercent,plan.Proration,plan.CategoryId,plan.LateFee,plan.GraceDays,memberCount=count,fraction,exemption,memberStatus=member?.Status,memberFrom=member?.EffectiveFrom,memberTo=member?.EndsAt})};db.Add(assessment);if(!plan.RequiresApproval&&!e.RequireInvoiceApproval)await Issue(invoice,e);access.Audit(plan.TenantId,"finance.dues.assessed",assessment.Id);return assessment;}
 public async Task<List<System.Text.Json.Nodes.JsonObject>> Enrich(IEnumerable<FinanceInvoice> values){var rows=values.ToArray();var ids=rows.Where(i=>i.MembershipId!=null).Select(i=>i.MembershipId!.Value).Distinct().ToArray();var members=await(from m in db.Memberships join c in db.MembershipCategories on m.CategoryId equals c.Id where ids.Contains(m.Id) select new{m.Id,m.Number,m.ChapterId,category=c.Name}).ToDictionaryAsync(m=>m.Id);var unitIds=members.Values.Select(m=>m.ChapterId).Concat(rows.Where(i=>i.BilledUnitId!=null).Select(i=>i.BilledUnitId!.Value)).Distinct().ToArray();var tenant=rows.FirstOrDefault()?.TenantId??Guid.Empty;var units=unitIds.Length==0?[]:await db.Units.FromSqlInterpolated($"WITH RECURSIVE chain AS (SELECT * FROM \"Units\" WHERE \"TenantId\"={tenant} AND \"Id\"=ANY({unitIds}) UNION SELECT p.* FROM \"Units\" p JOIN chain c ON c.\"ParentId\"=p.\"Id\" WHERE p.\"TenantId\"={tenant}) SELECT * FROM chain").ToArrayAsync();var kind=await db.Levels.Where(l=>l.TenantId==tenant).ToDictionaryAsync(l=>l.Id,l=>l.Kind);var lookup=units.ToDictionary(u=>u.Id);var result=new List<System.Text.Json.Nodes.JsonObject>();foreach(var i in rows){var json=JsonSerializer.SerializeToNode(FinanceEndpoints.InvoiceDto(i),FinanceExport.Web)!.AsObject();var member=i.MembershipId!=null?members.GetValueOrDefault(i.MembershipId.Value):null;var chapter=member?.ChapterId??i.BilledUnitId;json["memberNumber"]=member?.Number;json["category"]=member?.category;json["chapter"]=chapter!=null&&lookup.TryGetValue(chapter.Value,out var u)?u.Name:null;var next=chapter;var region="";for(var depth=0;depth<50&&next!=null&&lookup.TryGetValue(next.Value,out var ancestor);depth++){if(kind.GetValueOrDefault(ancestor.LevelId)=="Region"){region=ancestor.Name;break;}next=ancestor.ParentId;}json["region"]=region;json["overdueDays"]=i.Status=="Issued"&&i.Kind=="Invoice"&&i.Total>i.Paid+i.Credited?Math.Max(0,Today.DayNumber-i.DueOn.DayNumber):0;result.Add(json);}return result;
